function validate([nums, threshold]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 50000) return 'nums needs 1 to 50,000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Each value of nums is a whole number from 1 to 10^6.';
  if (!Number.isInteger(threshold) || threshold < nums.length || threshold > 1000000) return 'threshold is a whole number from nums.length to 10^6.';
  return null;
}

