function smallestDivisor(nums, threshold) {
  let left = 1;
  let right = Math.max(...nums);

  while (left < right) {
    const mid = Math.floor((left + right) / 2);
    let total = 0;
    for (const num of nums) {
      total += Math.ceil(num / mid);
    }
    if (total <= threshold) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }
  return left;
}

