function smallestDivisor(nums, threshold) {
  for (let divisor = 1; ; divisor++) {
    let sum = 0;
    for (const value of nums) sum += Math.floor((value + divisor - 1) / divisor);
    if (sum <= threshold) return divisor;
  }
}

