function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    const n = int(1500, 2000);
    const top = rand() < 0.5 ? 1000000 : int(1000, 1000000);
    const nums = Array.from({ length: n }, () => int(1, top));
    const roll = rand();
    let threshold;
    if (roll < 0.4) threshold = int(n, 2 * n);
    else if (roll < 0.8) threshold = int(n, 50 * n);
    else threshold = int(n, 1000000);
    return [nums, threshold];
  }
  const n = int(1, 6);
  const top = [3, 10, 40, 100][int(0, 3)];
  const nums = Array.from({ length: n }, () => int(1, top));
  if (rand() < 0.2) nums.fill(nums[0]);
  const threshold = rand() < 0.2 ? n : int(n, n + 25);
  return [nums, threshold];
}
